// Zag Store's bridge to zag-isideload (AppleAuthCore/zag-apple-bridge).
// Generated by hand from src/ffi.rs; scripts/test-zag-apple-bridge.sh checks
// that every exported symbol is declared here.
//
// Every call returns at once; results arrive as JSON through the callback on
// a bridge thread, and the bytes are wiped after it returns. Each started
// operation delivers exactly one terminal event ("signedIn", "result" or
// "failed"). Network access exists only in a build with the `live` feature.

#ifndef ZAG_APPLE_BRIDGE_H
#define ZAG_APPLE_BRIDGE_H

#include <stddef.h>
#include <stdint.h>

#define ZAG_BRIDGE_OK 0
#define ZAG_BRIDGE_DISABLED 1
#define ZAG_BRIDGE_INVALID 2
#define ZAG_BRIDGE_UNSUPPORTED 3

#define ZAG_BRIDGE_ANSWER_CODE 0
#define ZAG_BRIDGE_ANSWER_SMS 1
#define ZAG_BRIDGE_ANSWER_CANCEL 2

typedef void (*zag_bridge_event_callback)(void *context, const uint8_t *json, size_t length);

typedef struct ZagBridgeStorage {
	void *context;
	int32_t (*store)(void *context, const char *key, const uint8_t *value, size_t length);
	int32_t (*retrieve)(void *context, const char *key, uint8_t **value, size_t *length);
	int32_t (*delete_item)(void *context, const char *key);
	void (*release)(void *context, uint8_t *value, size_t length);
} ZagBridgeStorage;

int32_t zag_bridge_live_compiled(void);
int32_t zag_bridge_configure_live(const char *anisette_url, const ZagBridgeStorage *storage);
int32_t zag_bridge_configure_mock(const uint8_t *json, size_t length);

uint64_t zag_bridge_open_slot(void);
void zag_bridge_close_slot(uint64_t slot);

void zag_bridge_sign_in(uint64_t slot, const uint8_t *email, size_t email_length,
						const uint8_t *password, size_t password_length,
						void *context, zag_bridge_event_callback callback);
int32_t zag_bridge_answer(uint64_t slot, int32_t action, const uint8_t *code, size_t code_length);
int32_t zag_bridge_cancel(uint64_t slot);
void zag_bridge_portal(uint64_t slot, const uint8_t *credential, size_t credential_length,
					   const uint8_t *request, size_t request_length,
					   void *context, zag_bridge_event_callback callback);

#endif
